   var catalog=CreateStory(); var menu=Panel(tr,"TitleMenu",new Color(.015f,.025f,.07f,.97f),Vector2.zero,Vector2.one);Label(menu.transform,"TOKEN SURVIVAL",44,TextAnchor.MiddleCenter,new Vector2(.12f,.7f),new Vector2(.88f,.88f),new Color(.4f,.9f,1));var sub=Label(menu.transform,"Subtitle",21,TextAnchor.MiddleCenter,new Vector2(.16f,.55f),new Vector2(.84f,.7f),Color.white);var nb=Button(menu.transform,"开始新生活",new Vector2(.32f,.38f),new Vector2(.68f,.49f));var cb=Button(menu.transform,"继续游戏",new Vector2(.32f,.26f),new Vector2(.68f,.37f));var sb=Button(menu.transform,"声音：开启",new Vector2(.32f,.14f),new Vector2(.68f,.25f));
