   var confirm=Panel(tr,"ConfirmNewGame",new Color(.02f,.035f,.09f,.98f),new Vector2(.22f,.3f),new Vector2(.78f,.7f));Label(confirm.transform,"重新开始会覆盖当前存档",24,TextAnchor.MiddleCenter,new Vector2(.08f,.58f),new Vector2(.92f,.82f),Color.white);var yes=Button(confirm.transform,"确认开始",new Vector2(.1f,.2f),new Vector2(.45f,.4f));var no=Button(confirm.transform,"取消",new Vector2(.55f,.2f),new Vector2(.9f,.4f));confirm.SetActive(false);var ending=Panel(tr,"EndingChoice",new Color(.015f,.025f,.07f,.98f),new Vector2(.2f,.24f),new Vector2(.8f,.76f));Label(ending.transform,"尾声完成",32,TextAnchor.MiddleCenter,new Vector2(.1f,.68f),new Vector2(.9f,.86f),new Color(.45f,.9f,1));Label(ending.transform,"这间小工作室还会继续发光。",21,TextAnchor.MiddleCenter,new Vector2(.1f,.53f),new Vector2(.9f,.66f),Color.white);var free=Button(ending.transform,"自由探索",new Vector2(.12f,.28f),new Vector2(.44f,.43f));var quit=Button(ending.transform,"退出游戏",new Vector2(.56f,.28f),new Vector2(.88f,.43f));ending.SetActive(false);
