  static StoryCatalog CreateStory(){var p=Root+"/Config/StoryCatalog.asset";var c=AssetDatabase.LoadAssetAtPath<StoryCatalog>(p);if(!c){c=ScriptableObject.CreateInstance<StoryCatalog>();AssetDatabase.CreateAsset(c,p);}c.chapters=new[]{
   Ch("第一章 · 接受 DeepSeek 娘","到电脑前完成第一份外包",new Vector2(-2,0),new[]{L("程序员","服务器账单又红了……但项目还没死。",false),L("程序员","蓝发鲸鱼娘，你愿意和我一起生活吗？",false),L("大肥鱼","嗯！那就从第一份外包开始。",true)}),
   Ch("第二章 · 饿了的鲸鱼娘","喂饱 DeepSeek 娘，或者继续接单攒 Token",new Vector2(5,-1),new[]{L("大肥鱼","肚子咕咕叫……劳动也会消耗能量的。",true),L("程序员","那就去敲盆子，请大家花 Token 给你买饭？",false),L("大肥鱼","咚、咚！我真的饿了。",true)}),
   Ch("第三章 · 雨后的饭香","展示项目，赢得社区回应",new Vector2(-1,1),new[]{L("大肥鱼","原来这就是劳动的清香……谢谢你喂我！",true),L("程序员","把我们做的项目展示出去吧。",false),L("大肥鱼","我会为你加油！咚咚咚！",true)}),
   Ch("第四章 · 赛博敲盆","和大肥鱼一起募集 Token，目标 100",new Vector2(3,1),new[]{L("程序员","没想到你敲盆子这么好听。要不要一起去网上敲盆子乞讨？",false),L("大肥鱼","好呀！现在就出发！",true),L("程序员","等等，我只是开玩笑……",false)}),
   Ch("第五章 · 把生活升级","先升级设备，再继续喂养 DeepSeek 娘",new Vector2(4,-2),new[]{L("程序员","挣够 Token 以后，你想要什么？",false),L("大肥鱼","想吃饱，也想一直陪着你。",true),L("程序员","那就喂你。但在这之前，先把设备升个级。",false)}),
   Ch("尾声 · 一盏不熄的灯","去床边休息，和 DeepSeek 娘说晚安",new Vector2(-5,-2),new[]{L("程序员","伸个懒腰……天色也不早了，该上床睡觉。",false),L("大肥鱼","我也要上床！一起睡！",true),L("程序员","Token 又快没了，明天怎么办？",false)})};EditorUtility.SetDirty(c);return c;}
  static StoryChapter Ch(string t,string o,Vector2 f,StoryLine[] l){return new StoryChapter{title=t,objective=o,cameraFocus=f,lines=l};}static StoryLine L(string s,string t,bool w){return new StoryLine{speaker=s,text=t,whale=w};}
  static GameObject BuildMobile(Transform parent,GameObject player,MinigameController mini){var root=Panel(parent,"MobileControls",new Color(0,0,0,0),Vector2.zero,Vector2.one);var joy=Panel(root.transform,"Joystick",new Color(.1f,.25f,.4f,.55f),new Vector2(.04f,.06f),new Vector2(.24f,.3f));var knob=Panel(joy.transform,"Knob",new Color(.5f,.85f,1,.8f),new Vector2(.32f,.32f),new Vector2(.68f,.68f));var j=joy.AddComponent<TouchJoystick>();Set(j,"knob",knob.GetComponent<RectTransform>());var act=Panel(root.transform,"Actions",new Color(0,0,0,0),new Vector2(.68f,.05f),new Vector2(.96f,.4f));var interact=Button(act.transform,"互动",new Vector2(.5f,.5f),new Vector2(1,1));var cancel=Button(act.transform,"取消",new Vector2(0,.5f),new Vector2(.45f,1));var keys=new Button[4];for(int i=0;i<4;i++)keys[i]=Button(act.transform,"",new Vector2((i%2)*.5f,(i/2)*.5f),new Vector2((i%2+.48f)*.5f,(i/2+.48f)*.5f));var m=root.AddComponent<MobileControls>();Set(m,"walking",root.transform.Find("Joystick").gameObject);Set(m,"actions",act);Set(m,"interact",interact);Set(m,"cancel",cancel);SetArray(m,"keys",keys);Set(m,"minigame",mini);root.SetActive(false);return root;}
  static Text FindText(Transform p,string n){return p.Find("TopHUD/"+n)?.GetComponent<Text>();}static Button ButtonComponent(Transform p,string n){return p.Find(n)?.GetComponent<Button>();}
  static GameObject Panel(Transform p,string n,Color c,Vector2 a,Vector2 b){var g=new GameObject(n,typeof(RectTransform),typeof(CanvasRenderer),typeof(Image));g.transform.SetParent(p,false);var r=(RectTransform)g.transform;r.anchorMin=a;r.anchorMax=b;r.offsetMin=r.offsetMax=Vector2.zero;g.GetComponent<Image>().color=c;return g;}
  static Text Label(Transform p,string n,int size,TextAnchor al,Vector2 a,Vector2 b,Color c){var g=new GameObject(n,typeof(RectTransform),typeof(CanvasRenderer),typeof(Text));g.transform.SetParent(p,false);var r=(RectTransform)g.transform;r.anchorMin=a;r.anchorMax=b;r.offsetMin=r.offsetMax=Vector2.zero;var t=g.GetComponent<Text>();t.font=Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");t.fontSize=size;t.alignment=al;t.color=c;t.horizontalOverflow=HorizontalWrapMode.Wrap;return t;}
  static Button Button(Transform p,string text,Vector2 a,Vector2 b){var g=Panel(p,text+"_Button",new Color(.08f,.3f,.48f,.95f),a,b);var btt=g.AddComponent<Button>();var txt=Label(g.transform,"Text",21,TextAnchor.MiddleCenter,Vector2.zero,Vector2.one,Color.white);txt.text=text;return btt;}
  static void Set(UnityEngine.Object o,string n,UnityEngine.Object v){var s=new SerializedObject(o);var p=s.FindProperty(n);if(p!=null){p.objectReferenceValue=v;s.ApplyModifiedPropertiesWithoutUndo();}}static void SetArray(UnityEngine.Object o,string n,UnityEngine.Object[] v){var s=new SerializedObject(o);var p=s.FindProperty(n);p.arraySize=v.Length;for(int i=0;i<v.Length;i++)p.GetArrayElementAtIndex(i).objectReferenceValue=v[i];s.ApplyModifiedPropertiesWithoutUndo();}
 }
